/* ---------- Term 2 (Weeks 12 to 16): Grade 3 topics. Original exercises. ---------- */
/* Grade 3 English is written at Grade 4 level and goes straight into G3_ENGLISH (see data.js). */
G3_ENGLISH.push(
 TP("Adverbs and adverbials","",[
  pg("Adverbs Add Detail","Read the big idea. Then circle the adverb in each sentence.","Know that adverbs tell us how, when, where and how often.",
   CN(["snail","person-running"],"An adverb adds detail to a verb. It tells us how (slowly), when (yesterday), where (outside) or how often (always) something happens. Some adverbs also tell us how much: very, quite, too.","Adverbs"),
   CH("",[["The snail crawled slowly across the path.",["crawled","slowly"],1],["We always walk to school.",["always","walk"],0],["The guests arrived early.",["guests","early"],1],["Put the plates here, please.",["here","plates"],0],["The kite flew very high.",["very","kite"],0]])),
  pg("How, When, Where, How Often","Sort the adverbs into the right group.","Group adverbs by the question they answer.",
   SO("",["how","when","where","how often"],["neatly","tomorrow","upstairs","never","bravely","soon","nearby","rarely"],[0,1,2,3,0,1,2,3]),
   BK(["neatly","soon","nearby","rarely"]),F("Now use one adverb from each group.",["How: The boy wrote {{neatly}} in his book.","When: The parcel will come {{soon}}.","Where: Our cousins live {{nearby}}.","How often: Owls {{rarely}} fly in the daytime."])),
  pg("Adverbial Phrases","Read the big idea. Then underline the adverbial phrase.","Know that a group of words can work like an adverb.",
   CN(["owl","crescent-moon"],"An adverbial is a word or group of words that tells us more about a verb. A group of words is called an adverbial phrase: after lunch, in the garden, as quickly as he could.","Adverbials"),
   CH("Which part is the adverbial?",[["The owl hooted in the middle of the night.",["The owl hooted","in the middle of the night"],1],["After school, we played cricket.",["After school","we played cricket"],0],["Bilal searched under his bed.",["under his bed","Bilal searched"],0],["She finished the puzzle in ten minutes.",["She finished","in ten minutes"],1],["With a loud bang, the door closed.",["With a loud bang","the door closed"],0]])),
  pg("Fronted Adverbials","Read the rule. Then add the comma.","Use a comma after a fronted adverbial.",
   NO("When an adverbial comes at the start of a sentence, it is called a fronted adverbial. We put a comma after it: Before breakfast, I said my prayers. In the morning, the market is busy."),
   F("Write the word that comes just before the comma.",["Early this morning the rain stopped. → Early this {{morning}}, the rain stopped.","Without a sound the cat crept closer. → Without a {{sound}}, the cat crept closer.","Next week we are visiting Hunza. → Next {{week}}, we are visiting Hunza.","Under the old tree we found a nest. → Under the old {{tree}}, we found a nest."],1),
   WR("Write two sentences that start with a fronted adverbial.",["____________________, ____________________.","____________________, ____________________."])),
  pg("Move the Adverbial","Rewrite each sentence with the adverbial at the front.","Move adverbials to vary sentences.",
   F("",["We went to the beach on Sunday. → On Sunday, we {{went}} to the beach.","The children laughed during the play. → {{During}} the play, the children laughed.","The bus stopped at the corner. → At the corner, the {{bus}} stopped.","Ammi made tea as soon as we got home. → As soon as we got {{home}}, Ammi made tea."],1),
   NO("Moving an adverbial to the front changes how a sentence sounds. Good writers mix both kinds.")),
  pg("Adverbs of Degree","Choose the adverb from the box that fits best.","Use adverbs that show how much.",BK(["very","too","quite","almost","extremely","hardly"]),
   F("",["The tea is {{too}} hot to drink, so I will wait.","The test was {{quite}} easy, but one question was tricky.","I have {{almost}} finished. Just one more line!","K2 is an {{extremely}} high mountain.","It was so dark that I could {{hardly}} see.","The puppy is {{very}} small and fluffy."]),
   NO("Adverbs of degree make another word stronger or weaker: very tired, quite tired, too tired.")),
  pg("Comparing Adverbs","Fill in the table.","Use more, most, -er and -est with adverbs.",
   NO("Short adverbs add -er and -est: fast, faster, fastest. Most -ly adverbs use more and most: carefully, more carefully, most carefully. Watch out: well, better, best."),
   F("",["fast, {{faster}}, fastest","hard, harder, {{hardest}}","soon, {{sooner}}, soonest","quietly, {{more quietly}}, most quietly","carefully, more carefully, {{most carefully}}","well, {{better}}, best","badly, worse, {{worst}}"],1)),
  pg("Pick the Best Adverb","Look at each picture. Write a fitting adverb from the box.","Choose precise adverbs for actions.",BK(["gracefully","noisily","patiently","brightly","gently","loudly"]),
   FP("",[["butterfly","The butterfly flew {{gracefully}} over the flowers."],["drum","Hamza banged the drum {{noisily}}."],["fish","Nana waited {{patiently}} for a fish to bite."],["star","The stars twinkled {{brightly}} in the sky."],["baby","Khala rocked the baby {{gently}} to sleep."],["bell","The school bell rang {{loudly}}."]],2)),
  pg("Adverbials in a Story","Read the story. Then fill in the blanks.","Find adverbials in a text.",
   PA("Late one evening, Zain heard a strange noise. He tiptoed carefully down the stairs. In the kitchen, a tiny kitten was crying softly behind the fridge. Very gently, Zain lifted it out. The next morning, the whole family named her Biscuit."),
   F("",["The fronted adverbial of time in the first sentence is {{Late}} one evening.","Zain went down the stairs {{carefully}}.","The kitten was crying {{softly}}.","Where was the kitten? {{In}} the kitchen, behind the fridge.","An adverb of degree in the story is {{Very}}."])),
  pg("Write with Adverbials","Plan and write a short paragraph. Then draw a picture.","Use adverbs and fronted adverbials in writing.",
   WR("Write about a rainy day. Use at least one adverb of how, one of when and one fronted adverbial with a comma.",["____________________________________________","____________________________________________","____________________________________________","____________________________________________"]),DR("Draw your rainy day",170))],
  "Adverbs and adverbials at Grade 4 level: adverbs of how, when, where and how often, adverbs of degree (very, quite, too), adverbial phrases, fronted adverbials with a comma, and comparing adverbs (faster, more carefully, better).",
  ["Ask how? when? where? how often? about each verb in a sentence.","Point out fronted adverbials in story books and look for the comma.","Practise moving an adverbial from the end of a sentence to the front."],
  ["Play adverb charades: act out a task in the manner of an adverb (sleepily, angrily) while others guess.","Write a recipe together and start each step with an adverbial: First, After two minutes, Finally."],
  "Children often forget the comma after a fronted adverbial, or think every -ly word is an adverb. Friendly and lovely are adjectives.",
  ["The Midnight Visitor","Late at night, Sana woke up suddenly. Outside her window, something was tapping gently. She peeped carefully through the curtain. On the branch, a little owl sat quietly, blinking its big eyes. Ask: Find two fronted adverbials in the story."])
);

addPlus("maths",{g3:[
 TP("Multiplying 2-digit numbers","",[
  pg("Multiplying by 10","Read the big idea. Then fill in the answers.","Multiply numbers by 10 and 100.",
   CN(["input-numbers","abacus"],"When we multiply by 10, each digit moves one place to the left and a zero fills the ones place. 23 × 10 = 230. When we multiply by 100, the digits move two places: 23 × 100 = 2300.","Times 10 and 100"),
   F("",["14 × 10 = {{140}}","36 × 10 = {{360}}","50 × 10 = {{500}}","7 × 100 = {{700}}","25 × 100 = {{2500}}","{{48}} × 10 = 480"],2)),
  pg("Multiples of 10","Use the facts you know.","Multiply by multiples of 10.",
   NO("To work out 30 × 4, think 3 × 4 = 12, so 30 × 4 = 120. It is ten times bigger."),
   F("",["20 × 3 = {{60}}","40 × 5 = {{200}}","60 × 4 = {{240}}","70 × 3 = {{210}}","90 × 2 = {{180}}","80 × 6 = {{480}}"],2)),
  pg("Split It Up","Partition the 2-digit number, multiply each part, then add.","Multiply a 2-digit number by a 1-digit number by partitioning.",
   NO("23 × 4: split 23 into 20 and 3. 20 × 4 = 80 and 3 × 4 = 12. Add: 80 + 12 = 92."),
   F("",["16 × 3: 10 × 3 = {{30}}, 6 × 3 = {{18}}, total {{48}}","24 × 4: 20 × 4 = {{80}}, 4 × 4 = {{16}}, total {{96}}","35 × 2: 30 × 2 = {{60}}, 5 × 2 = {{10}}, total {{70}}","42 × 5: 40 × 5 = {{200}}, 2 × 5 = {{10}}, total {{210}}"],1)),
  pg("The Grid Method","Fill in each grid. Then add the parts.","Use the grid method to multiply.",
   NO("For 34 × 6, make a grid: 30 × 6 = 180 and 4 × 6 = 24. Then 180 + 24 = 204."),
   F("",["27 × 3 → 20 × 3 = {{60}} | 7 × 3 = {{21}} | answer {{81}}","45 × 4 → 40 × 4 = {{160}} | 5 × 4 = {{20}} | answer {{180}}","38 × 5 → 30 × 5 = {{150}} | 8 × 5 = {{40}} | answer {{190}}","63 × 7 → 60 × 7 = {{420}} | 3 × 7 = {{21}} | answer {{441}}"],1)),
  pg("Column Method","Read the big idea. Then work out each one in columns.","Use the short column method.",
   CN(["pencil","notebook"],"In the column method we multiply the ones first. 26 × 3: 6 × 3 = 18, write 8 and carry 1 ten. Then 2 tens × 3 = 6 tens, add the 1 carried: 7 tens. The answer is 78.","Column method"),
   F("",["14 × 6 = {{84}}","25 × 3 = {{75}}","37 × 2 = {{74}}","19 × 5 = {{95}}","46 × 4 = {{184}}","58 × 3 = {{174}}"],2)),
  pg("Two 2-digit Numbers","Use a grid to multiply two 2-digit numbers.","Multiply a 2-digit number by a 2-digit number.",
   NO("12 × 13: split both numbers. 10 × 10 = 100, 10 × 3 = 30, 2 × 10 = 20, 2 × 3 = 6. Add: 100 + 30 + 20 + 6 = 156."),
   F("",["11 × 12 = 100 + 20 + 10 + 2 = {{132}}","14 × 11 = 100 + 10 + 40 + 4 = {{154}}","21 × 13 = 200 + 60 + 10 + 3 = {{273}}","15 × 12 = 100 + 20 + 50 + 10 = {{180}}"],1)),
  pg("Picture Problems","Look at each picture. Write the multiplication and the answer.","Use multiplication in real life.",
   FP("",[["egg","A tray holds 30 eggs. 4 trays hold {{120}} eggs."],["books","A shelf holds 24 books. 3 shelves hold {{72}} books."],["bus","A bus has 45 seats. 2 buses have {{90}} seats."],["red-apple","A box has 18 apples. 5 boxes have {{90}} apples."],["coin","A pen costs Rs 35. 4 pens cost Rs {{140}}."],["cricket","A team scores 26 runs each over. In 3 overs: {{78}} runs."]],2)),
  pg("Word Problems","Read carefully. Underline the numbers. Then solve.","Solve one-step and two-step word problems.",
   WP("",["A school has 6 classes with 32 children in each. There are {{192}} children.","A mango crate holds 24 mangoes. Abbu buys 5 crates. He has {{120}} mangoes.","A rickshaw ride costs Rs 85. Nani takes 2 rides. She pays Rs {{170}}.","Hira reads 15 pages a day for 7 days. She reads {{105}} pages.","There are 12 rows of 13 chairs in the hall. There are {{156}} chairs."])),
  pg("Estimate First","Round, estimate, then work out the real answer.","Estimate to check answers.",
   NO("Before you multiply, round to the nearest 10. 29 × 4 is about 30 × 4 = 120. The real answer, 116, is close, so it makes sense."),
   F("",["41 × 3 is about {{120}}. Real answer: {{123}}","58 × 2 is about {{120}}. Real answer: {{116}}","22 × 5 is about {{100}}. Real answer: {{110}}","69 × 4 is about {{280}}. Real answer: {{276}}"],1)),
  pg("Number Detective","Solve the puzzles. Then make your own.","Reason about multiplication.",
   CH("Circle the correct answer.",[["Which is bigger?",["23 × 4","25 × 3"],0],["Which answer is wrong?",["16 × 5 = 80","17 × 5 = 75"],1],["Which is the same as 24 × 3?",["20 × 3 + 4 × 3","20 × 3 + 4"],0],["Which is closest to 200?",["49 × 4","38 × 4"],0]]),
   WR("Write a word problem for 27 × 4 and solve it.",["____________________________________________","____________________________________________ Answer: ______"]))],
  "Multiplying 2-digit numbers: times 10 and 100, multiples of 10, partitioning, the grid method, the short column method, a first look at 2-digit × 2-digit using a grid, estimating and word problems.",
  ["Make sure times tables to 10 × 10 are quick before starting.","Say the parts out loud: 23 × 4 is 20 fours and 3 fours.","Estimate first, then check if the answer is sensible."],
  ["At the shop, work out the cost of several of the same item, for example 3 packets at Rs 45.","Count eggs in trays or chairs in rows and multiply."],
  "Children often forget to add the carried ten in the column method, or multiply only the ones digit. The grid method helps them see both parts.",
  ["The Mango Stall","Chacha had a mango stall in Multan. Each crate held 24 mangoes. One morning he sold 6 crates! He split 24 into 20 and 4: 20 × 6 is 120 and 4 × 6 is 24. Ask: How many mangoes did he sell?"])
]});

addPlus("science",{g3:[
 TP("Food chains","",[
  pg("Energy from the Sun","Read the big idea. Then circle true or false.","Know that food chains start with the Sun and plants.",
   CN(["sun","herb"],"All living things need food for energy. Green plants make their own food using sunlight, water and air. Animals cannot do this, so they eat plants or other animals. A food chain shows who eats what.","Food chains"),
   CH("",[["Green plants make their own food.",0],["Animals make food from sunlight.",1],["A food chain shows who eats what.",0],["Every food chain starts with a plant.",0]],TF)),
  pg("Producers and Consumers","Write producer or consumer for each living thing.","Tell producers and consumers apart.",BK(["producer","consumer"]),
   NO("A producer makes its own food (plants). A consumer eats other living things for food (animals)."),
   FP("",[["herb","grass: {{producer}}"],["rabbit","rabbit: {{consumer}}"],["sunflower","sunflower: {{producer}}"],["eagle","eagle: {{consumer}}"],["deciduous-tree","tree: {{producer}}"],["frog","frog: {{consumer}}"]],3)),
  pg("Follow the Arrows","Read the food chain. Fill in the blanks.","Read a food chain with arrows.",BK(["grass","caterpillar","bird","eats","energy"]),
   CY("",[["herb","{{grass}}"],["bug","{{caterpillar}}"],["bird","{{bird}}"],["fox","fox"]]),
   NO("The arrow means is eaten by. It shows which way the energy goes."),
   F("",["The caterpillar {{eats}} the grass.","The arrows show the {{energy}} moving along the chain."])),
  pg("Herbivores, Carnivores, Omnivores","Sort the animals.","Group animals by what they eat.",
   NO("Herbivores eat only plants. Carnivores eat only animals. Omnivores eat both plants and animals."),
   SO("",["herbivore","carnivore","omnivore"],["cow","lion","bear","goat","shark","chicken","rabbit","eagle","human"],[0,1,2,0,1,2,0,1,2])),
  pg("Predator and Prey","Read the big idea. Then choose the answer.","Know what predators and prey are.",
   CN(["eagle","snake"],"A predator hunts and eats other animals. The animal it eats is its prey. An animal can be both: a snake is a predator of mice, but it is prey for an eagle.","Predator and prey"),
   CH("",[["An owl catches a mouse. The owl is the",["predator","prey"],0],["A frog eats a fly. The fly is the",["predator","prey"],1],["A shark eats a fish. The fish is the",["predator","prey"],1],["A snake eats a frog. The snake is the",["predator","prey"],0],["Which animal can be both predator and prey?",["snake","grass"],0]])),
  pg("Build a Chain","Put each food chain in the right order. Start with the producer.","Order living things in a food chain.",
   F("",["frog, grass, snake, grasshopper → {{grass}} → grasshopper → {{frog}} → snake","fox, rabbit, carrot → {{carrot}} → {{rabbit}} → fox","small fish, shark, seaweed → {{seaweed}} → small fish → {{shark}}","snake, seeds, eagle, mouse → seeds → {{mouse}} → {{snake}} → eagle"],1)),
  pg("Decomposers","Read. Then fill in the blanks.","Know what decomposers do.",BK(["rot","soil","mushrooms","worms","recycle"]),
   PA("When plants and animals die, they do not stay forever. Decomposers break them down. Mushrooms, worms and tiny germs called bacteria are decomposers. They make dead things rot and turn them back into soil. The soil feeds new plants. Decomposers help nature recycle."),
   FP("",[["mushroom","{{mushrooms}} are decomposers."],["worm","{{worms}} help break down dead leaves."],["fallen-leaf","Dead leaves {{rot}} away."],["seedling","Rich {{soil}} helps new plants grow."]],2),
   F("",["Decomposers help nature {{recycle}}."])),
  pg("What If?","Think about the food chain. Then answer.","Predict what happens when a food chain changes.",
   NO("Food chain: grass → rabbit → fox."),
   CH("",[["If all the grass died, the rabbits would",["go hungry","have more food"],0],["If there were no foxes, the number of rabbits would",["go up","go down"],0],["If there were too many rabbits, the grass would",["be eaten up","grow taller"],0],["If the rabbits got sick, the foxes would",["have less food","have more food"],0]])),
  pg("Food Chain Maths","Read and solve.","Use maths with food chain facts.",
   WP("",["A frog eats 12 flies a day. In 7 days it eats {{84}} flies.","An owl catches 3 mice a night. In 10 nights it catches {{30}} mice.","A field had 50 rabbits. Foxes caught 14. There were {{36}} rabbits left.","A caterpillar eats 4 leaves an hour. In 6 hours it eats {{24}} leaves."])),
  pg("My Food Chain","Draw a food chain from a place in Pakistan. Label it.","Make and explain a food chain.",
   WR("Choose a place: a river, a forest, a desert or the sea.",["My place: ____________________","Producer: ______________ → first consumer: ______________","→ next consumer: ______________ → top predator: ______________","If the producer disappeared, ____________________________."]),DR("Draw your food chain with arrows",190))],
  "Food chains: plants are producers that make food from sunlight, animals are consumers. Arrows show energy moving. Herbivores, carnivores and omnivores, predators and prey, decomposers, and what happens when a chain changes.",
  ["Check that arrows point from the food to the eater.","Ask what your child ate for lunch and trace it back to a plant.","Talk about animals that are both predators and prey."],
  ["Look under a stone or a pile of leaves for decomposers like worms.","Make a paper chain with one living thing on each link."],
  "Children often draw the arrow the wrong way, from the eater to the food. The arrow means is eaten by and shows where the energy goes.",
  ["The Hungry Owl","In a wheat field near Faisalabad, mice nibbled the grain. A snake slid through the stalks looking for mice. High above, an owl watched the snake. The farmer smiled: the owl and snake kept the mice from eating his crop. Ask: Write this food chain with arrows."])
]});

addPlus("history",{g3:[
 TP("The Mughal empire","",[
  pg("Who Were the Mughals?","Read the big idea. Then circle true or false.","Know when the Mughal empire began.",
   CN(["crown","castle"],"The Mughals ruled much of South Asia for over 300 years. The first Mughal emperor, Babur, came from Central Asia and won the Battle of Panipat in 1526. The empire grew to include the land that is Pakistan today.","The Mughals"),
   CH("",[["Babur was the first Mughal emperor.",0],["The Mughal empire began in 1526.",0],["The Mughals ruled for only 10 years.",1],["Lahore was part of the Mughal empire.",0]],TF)),
  pg("The Great Mughals","Read the timeline. Fill in the blanks.","Name the first six Mughal emperors in order.",BK(["Babur","Humayun","Akbar","Jahangir","Shah Jahan","Aurangzeb"]),
   CY("",[["crown","1. {{Babur}}"],["crown","2. {{Humayun}}"],["crown","3. {{Akbar}}"],["crown","4. {{Jahangir}}"],["crown","5. {{Shah Jahan}}"],["crown","6. {{Aurangzeb}}"]])),
  pg("Akbar the Great","Read. Then answer the questions.","Know why Akbar is remembered.",
   PA("Akbar became emperor when he was only 13 years old. He ruled for almost 50 years. Akbar made the empire bigger and stronger. He chose clever ministers to help him and listened to people from many backgrounds. He also rebuilt the Lahore Fort and lived in Lahore for many years."),
   F("",["Akbar became emperor at the age of {{13}}.","He ruled for almost {{50}} years.","He rebuilt the {{Lahore}} Fort.","He chose clever {{ministers}} to help him."])),
  pg("Mughal Buildings in Pakistan","Match each building to the emperor who built it.","Know famous Mughal buildings in Pakistan.",
   MA("Write the letter in the box.",["Badshahi Mosque, Lahore","Shalimar Gardens, Lahore","Tomb of Jahangir, Shahdara","Lahore Fort (rebuilt)"],["Aurangzeb","Shah Jahan","Nur Jahan and Shah Jahan, for Jahangir","Akbar"]),
   NO("The Taj Mahal in Agra, India, was built by Shah Jahan in memory of his wife Mumtaz Mahal.")),
  pg("Mughal Gardens","Read the big idea. Then fill in the blanks.","Describe a Mughal garden.",BK(["four","water","fountains","trees","shade"]),
   CN(["national-park","droplet"],"Mughal gardens were split into four parts by paths and water channels. They had fountains, fruit trees and flowers. People rested there in the shade on hot days.","Mughal gardens"),
   F("",["A Mughal garden was split into {{four}} parts.","Channels of {{water}} ran through it.","{{fountains}} sprayed cool water.","Fruit {{trees}} gave food and {{shade}}."])),
  pg("Arts and Crafts","Look at each picture. Circle Mughal or modern.","Know the arts of the Mughal period.",
   CP("",[["scroll","Small, detailed paintings called miniatures",0],["writing-hand","Beautiful handwriting called calligraphy",0],["gem-stone","Jewels set in gold and marble",0],["mobile-phone","Photos on a phone",1],["television","Cartoons on TV",1],["elephant","Decorated elephants in parades",0]],["Mughal","modern"])),
  pg("Life at Court","Read. Then circle the answer.","Know about life at the Mughal court.",
   PA("The emperor held court in a big hall. Nobles, soldiers and visitors came to see him. Persian was the language of the court and of books. Poets read poems, and painters made pictures of court life. Over time, Persian mixed with local languages, and this helped Urdu grow."),
   CH("",[["What was the language of the Mughal court?",["Persian","English"],0],["Who came to the court?",["nobles and visitors","only children"],0],["Which language grew partly from this mixing?",["Urdu","French"],0]])),
  pg("Mughal Timeline Maths","Read and solve.","Use dates to work out time.",
   WP("",["Babur won at Panipat in 1526. Akbar became emperor in 1556. That is {{30}} years later.","Shah Jahan began the Shalimar Gardens in 1641. That was {{385}} years before 2026.","Aurangzeb built the Badshahi Mosque in 1673. It is about {{350}} years old (round to the nearest 10).","The Mughal empire lasted from 1526 to 1857. That is {{331}} years."])),
  pg("The End of the Empire","Put the events in order. Fill in the missing words.","Know how the Mughal empire ended.",BK(["smaller","British","1857","last"]),
   CY("",[["crown","After Aurangzeb, the empire grew {{smaller}}"],["office-building","The {{British}} East India Company took more land"],["spiral-calendar","In {{1857}} there was a great uprising"],["scroll","Bahadur Shah Zafar was the {{last}} Mughal emperor"]])),
  pg("Be a Historian","Answer and draw.","Explain why the Mughals are important.",
   WR("",["One Mughal emperor I learnt about is ____________. He is famous for ____________________.","A Mughal building I would like to visit is ____________________.","The Mughals are important to Pakistan because ____________________."]),DR("Draw a Mughal building or garden",190))],
  "The Mughal empire (1526 to 1857): Babur and the first six emperors, Akbar, Mughal buildings in Lahore such as the Badshahi Mosque, Shalimar Gardens and Lahore Fort, gardens, miniature painting, Persian at court and the end of the empire.",
  ["Find Lahore, Agra and Delhi on a map.","Look at photos of the Badshahi Mosque and Shalimar Gardens together.","Make a family timeline and compare it with the Mughal timeline."],
  ["Visit the Lahore Fort, Badshahi Mosque or Shalimar Gardens, or watch a short video tour.","Try drawing a small miniature painting with fine pencils and bright colours."],
  "Children may think the Taj Mahal is in Pakistan. It is in Agra, India. The Mughal buildings in Pakistan include the Badshahi Mosque, Lahore Fort and Shalimar Gardens.",
  ["The Painter's Apprentice","Long ago in Lahore, a boy helped a court painter mix colours from stones and flowers. One day he painted a tiny bird on the edge of a picture of the emperor's garden. The painter smiled and said, 'Small things make a picture come alive.' Ask: What did the boy use to make colours?"])
]});

addPlus("geography",{g3:[
 TP("Climate zones of the world","",[
  pg("Weather and Climate","Read the big idea. Then circle weather or climate.","Tell the difference between weather and climate.",
   CN(["globe-showing-asia-australia","thermometer"],"Weather is what the air is like today. Climate is the usual weather of a place over many years. The world has different climate zones: hot, cold, dry and mild.","Climate"),
   CH("",[["It is raining in Lahore today.",0],["Karachi is usually warm all year.",1],["The Arctic is cold for most of the year.",1],["It will be windy this afternoon.",0]].map(x=>[x[0],["weather","climate"],x[1]]))),
  pg("The Equator and the Poles","Read. Then fill in the blanks.","Know why it is hotter near the Equator.",BK(["Equator","hottest","poles","coldest","straight"]),
   NO("The Equator is an imaginary line around the middle of the Earth. Near the Equator the Sun shines more straight down, so it is hot. Near the North and South Poles the sunlight is weak and spread out, so it is cold."),
   F("",["The line around the middle of the Earth is the {{Equator}}.","Places near the Equator are usually the {{hottest}}.","The {{poles}} are at the top and bottom of the Earth.","The poles are the {{coldest}} places.","Near the Equator, the sunlight comes more {{straight}} down."])),
  pg("Five Climate Zones","Write the zone for each picture.","Name the main climate zones.",BK(["tropical","desert","temperate","polar","mountain"]),
   FP("",[["palm-tree","Hot and wet all year: {{tropical}}"],["camel","Very dry, little rain: {{desert}}"],["deciduous-tree","Warm summers, cool winters: {{temperate}}"],["penguin","Icy cold, long winters: {{polar}}"],["snow-capped-mountain","Colder the higher you go: {{mountain}}"]],1)),
  pg("Rainforests","Read. Then circle true or false.","Describe the tropical climate.",
   PA("Tropical rainforests grow near the Equator, in places like the Amazon in South America and parts of Africa and Asia. It is hot all year and it rains almost every day. Tall trees grow close together. More kinds of plants and animals live here than anywhere else."),
   CH("",[["Rainforests grow near the Equator.",0],["It hardly ever rains in a rainforest.",1],["Many kinds of animals live in rainforests.",0],["The Amazon is in South America.",0]],TF)),
  pg("Deserts","Read the big idea. Then answer.","Describe the desert climate.",
   CN(["desert","cactus"],"A desert gets very little rain. Many deserts are hot in the day and cold at night. Plants such as cactus store water. Camels can go for days without drinking. The Thar desert in Sindh and the Sahara in Africa are deserts.","Deserts"),
   CH("",[["A desert gets",["very little rain","rain every day"],0],["At night a desert can be",["cold","always hot"],0],["Which plant stores water?",["cactus","rose"],0],["Which desert is in Pakistan?",["Thar","Sahara"],0]])),
  pg("Polar Lands","Read. Then fill in the blanks.","Describe the polar climate.",BK(["ice","penguins","polar bears","dark","fur"]),
   PA("The Arctic is around the North Pole and Antarctica is around the South Pole. They are covered in ice and snow. In winter it stays dark for weeks. Polar bears live in the Arctic and penguins live in Antarctica. Animals have thick fur, feathers or fat to keep warm."),
   F("",["Polar lands are covered in {{ice}} and snow.","{{penguins}} live in Antarctica.","{{polar bears}} live in the Arctic.","In winter it stays {{dark}} for weeks.","Thick {{fur}} keeps animals warm."])),
  pg("Climates of Pakistan","Look at the map. Then circle true or false.","Know that Pakistan has more than one climate.",
   {t:"map",rows:["mountain:Swat|snow-capped-mountain:Gilgit|snow-capped-mountain:Skardu","sun:Quetta|sun-behind-cloud:Islamabad|sun-behind-cloud:Lahore","desert:Kharan|sun:Karachi|desert:Thar"]},
   CH("",[["The north of Pakistan has a mountain climate.",0],["The Thar is a desert.",0],["Karachi has snowy winters.",1],["Pakistan has only one climate zone.",1],["Quetta is in the west of Pakistan.",0]],TF)),
  pg("Living in Each Climate","Match the climate to how people live.","Know how climate affects homes, clothes and food.",
   MA("Write the letter in the box.",["polar","desert","tropical","mountain","temperate"],["thick coats and warm homes","loose clothes and thick mud walls to stay cool","houses on stilts and big umbrellas","terrace farms on hillsides","four seasons of clothes"])),
  pg("Climate Graph","Read the table. Then solve.","Read temperature data and compare places.",
   NO("Usual temperature in January: Karachi 19°C, Lahore 13°C, Quetta 4°C, Skardu −2°C. In June: Karachi 31°C, Lahore 34°C, Quetta 26°C, Skardu 21°C."),
   WP("",["In January, Karachi is {{6}} degrees warmer than Lahore.","The hottest city in June is {{Lahore}}.","Quetta in June is {{22}} degrees warmer than in January.","Skardu goes from −2°C to 21°C. That is a rise of {{23}} degrees."])),
  pg("My Climate Fact File","Choose one climate zone. Fill in the fact file and draw.","Present facts about a climate zone.",
   WR("",["Climate zone: ____________________","Where in the world: ____________________","Weather there: ____________________","A plant and an animal that live there: ____________________","How people dress: ____________________"]),DR("Draw a scene from your climate zone",170))],
  "Climate zones of the world: weather and climate, the Equator and the poles, tropical, desert, temperate, polar and mountain climates, the many climates of Pakistan, and how climate shapes homes, clothes and food.",
  ["Find the Equator and the poles on a globe or atlas.","Compare today's weather in Karachi, Lahore and Skardu on a weather app.","Talk about what you pack for a trip to Murree compared to Karachi."],
  ["Make a climate zone poster with pictures cut from magazines.","Fill a jar with sand and one with soil, water them, and see which dries first."],
  "Children often mix up weather and climate. Weather changes day to day; climate is the usual pattern over many years.",
  ["Two Postcards","Ali's cousin in Skardu sent a postcard: 'Snow on the mountains, we wear three sweaters!' His friend in Karachi wrote: 'Warm and sunny, we went to the beach.' Both were sent on the same day in January. Ask: Why was the weather so different?"])
]});

addPlus("social",{g3:[
 TP("Provinces and their capitals","",[
  pg("Pakistan's Provinces","Read the big idea. Then circle true or false.","Know that Pakistan has four provinces.",
   CN(["world-map","round-pushpin"],"Pakistan has four provinces: Punjab, Sindh, Khyber Pakhtunkhwa and Balochistan. It also has the Islamabad Capital Territory, Gilgit-Baltistan and Azad Jammu and Kashmir. Each province has a capital city where its government works.","Provinces"),
   CH("",[["Pakistan has four provinces.",0],["Islamabad is the capital of Pakistan.",0],["Sindh is a city.",1],["Each province has its own capital city.",0]],TF)),
  pg("Match the Capital","Write the capital of each province.","Name provincial capitals.",BK(["Lahore","Karachi","Peshawar","Quetta","Islamabad"]),
   F("",["Punjab: {{Lahore}}","Sindh: {{Karachi}}","Khyber Pakhtunkhwa: {{Peshawar}}","Balochistan: {{Quetta}}"],2),
   NO("The capital of Gilgit-Baltistan is Gilgit. The capital of Azad Jammu and Kashmir is Muzaffarabad."),F("",["The capital of the whole country: {{Islamabad}}"],1)),
  pg("Find It on the Map","Look at the map. Then fill in the blanks.","Use a map to locate provinces.",
   {t:"map",rows:["round-pushpin:Peshawar (KP)|round-pushpin:Islamabad|snow-capped-mountain:Gilgit-Baltistan","round-pushpin:Quetta (Balochistan)|sheaf-of-rice:Punjab farms|round-pushpin:Lahore (Punjab)","gem-stone:Gwadar (Balochistan)|round-pushpin:Karachi (Sindh)|desert:Thar (Sindh)"]},
   F("",["Gilgit-Baltistan is in the far {{north}}.","Quetta is in the {{west}}, in Balochistan.","Karachi is in the {{south}}, by the sea.","Lahore is in the {{east}}, in Punjab."])),
  pg("Punjab","Read. Then answer the questions.","Know key facts about Punjab.",
   PA("Punjab means land of five rivers. More people live in Punjab than in any other province. Its fertile plains grow wheat, rice, cotton and sugarcane. Lahore is the capital. It has the Lahore Fort, the Badshahi Mosque and many universities."),
   F("",["Punjab means land of five {{rivers}}.","The capital of Punjab is {{Lahore}}.","Punjab has the most {{people}} of any province.","Punjab grows wheat, rice, cotton and {{sugarcane}}."])),
  pg("Sindh","Read the big idea. Then fill in the blanks.","Know key facts about Sindh.",BK(["Indus","Karachi","port","Mohenjo-daro"]),
   CN(["ship","classical-building"],"Sindh lies along the lower Indus River and the Arabian Sea. Karachi, its capital, is the biggest city in Pakistan and has the busiest port. The old city of Mohenjo-daro is in Sindh.","Sindh"),
   F("",["Sindh lies along the lower {{Indus}} River.","Its capital is {{Karachi}}.","Ships load and unload at Karachi's {{port}}.","The old city of {{Mohenjo-daro}} is in Sindh."])),
  pg("Khyber Pakhtunkhwa","Read. Then circle true or false.","Know key facts about Khyber Pakhtunkhwa.",
   PA("Khyber Pakhtunkhwa is in the north west of Pakistan. It has green valleys like Swat, high mountains and the famous Khyber Pass. Peshawar, its capital, is one of the oldest cities in South Asia. Many people speak Pashto."),
   CH("",[["Peshawar is the capital of Khyber Pakhtunkhwa.",0],["Swat is a green valley.",0],["Khyber Pakhtunkhwa is in the south of Pakistan.",1],["Many people there speak Pashto.",0]],TF)),
  pg("Balochistan","Read the big idea. Then answer.","Know key facts about Balochistan.",
   CN(["desert","gem-stone"],"Balochistan is the biggest province by land, but fewer people live there. It has deserts, mountains and a long coast with the port of Gwadar. It is rich in minerals and gas. Quetta is its capital and is famous for its fruit.","Balochistan"),
   CH("",[["Which is the biggest province by land?",["Balochistan","Punjab"],0],["Which port is in Balochistan?",["Gwadar","Karachi"],0],["What is the capital of Balochistan?",["Quetta","Peshawar"],0],["Balochistan is rich in",["minerals and gas","rainforests"],0]])),
  pg("Who Am I?","Read each clue. Write the province.","Recall facts about each province.",BK(["Punjab","Sindh","Khyber Pakhtunkhwa","Balochistan"]),
   F("",["My capital is Quetta and I have the most land. {{Balochistan}}","My name means five rivers. {{Punjab}}","I have the biggest port and Mohenjo-daro. {{Sindh}}","I have the Khyber Pass and Swat valley. {{Khyber Pakhtunkhwa}}"],1)),
  pg("Travel Maths","Read and solve.","Use distances and times between cities.",
   WP("",["Lahore to Islamabad is about 380 km. A return trip is about {{760}} km.","A bus from Karachi to Hyderabad takes 3 hours. Two trips take {{6}} hours.","Peshawar to Islamabad is about 190 km. Islamabad to Lahore is about 380 km. Peshawar to Lahore through Islamabad is about {{570}} km.","A train leaves Quetta at 9 am and the trip takes 5 hours. It arrives at {{2}} pm."])),
  pg("My Province","Fill in the fact file about your province. Then draw.","Describe your own province.",
   WR("",["I live in the province (or area) of ____________________.","Its capital is ____________________.","A famous place there is ____________________.","A food from my province is ____________________.","A language spoken there is ____________________."]),DR("Draw a famous place in your province",170))],
  "Provinces and capitals of Pakistan: Punjab (Lahore), Sindh (Karachi), Khyber Pakhtunkhwa (Peshawar), Balochistan (Quetta), plus Islamabad Capital Territory, Gilgit-Baltistan (Gilgit) and Azad Jammu and Kashmir (Muzaffarabad). Facts about land, people, crops and famous places, with map and travel problems.",
  ["Use a map of Pakistan to point to each province and its capital.","Talk about relatives or friends who live in other provinces.","Make flash cards with a province on one side and its capital on the other."],
  ["Cook or taste a dish from each province over a month.","Plan an imaginary road trip that visits all four provincial capitals."],
  "Children sometimes think Karachi is the capital of Pakistan. It was the first capital, but Islamabad has been the capital since the 1960s. Karachi is the capital of Sindh.",
  ["The Postcard Collection","Dada had a box of old postcards from his travels: the Khyber Pass, Karachi's beach, Lahore's Badshahi Mosque and the hills near Quetta. Every Sunday, Hira chose one and found the place on the map. Ask: Which provinces did Dada visit?"])
]});

addPlus("urdu",{g3:[
 TP("زمانہ","Tenses",[
  pg("زمانہ کیا ہے؟|What is tense?","بڑا خیال پڑھیں۔ پھر زمانہ پہچانیں۔","Know the three tenses in Urdu.",
   CN(["spiral-calendar","hourglass-done"],"فعل سے کام کے وقت کا پتا چلتا ہے۔ اسے زمانہ کہتے ہیں۔ زمانے تین ہیں: ماضی (گزرا ہوا وقت)، حال (موجودہ وقت) اور مستقبل (آنے والا وقت)۔","زمانہ"),
   CH("",[["میں نے کھانا کھایا۔",["ماضی","حال","مستقبل"],0],["میں کھانا کھا رہا ہوں۔",["ماضی","حال","مستقبل"],1],["میں کھانا کھاؤں گا۔",["ماضی","حال","مستقبل"],2],["وہ کل سکول گئی۔",["ماضی","حال","مستقبل"],0],["ہم کل پارک جائیں گے۔",["ماضی","حال","مستقبل"],2]])),
  pg("ماضی|Past tense","خانے سے صحیح فعل لکھ کر جملے مکمل کریں۔","Write verbs in the past tense.",BK(["پڑھی","کھیلا","لکھا","گئے","دیکھا","سوئی"]),
   NO("ماضی میں کام ہو چکا ہوتا ہے۔ جیسے: احمد نے خط لکھا۔"),
   F("",["کل علی نے کرکٹ {{کھیلا}}۔","سارہ نے کہانی {{پڑھی}}۔","میں نے خط {{لکھا}}۔","ہم پچھلے سال مری {{گئے}}۔","حمزہ نے چاند {{دیکھا}}۔","گڑیا جلدی {{سوئی}}۔"],2)),
  pg("حال|Present tense","صحیح فعل پر دائرہ لگائیں۔","Use the present tense.",
   NO("حال میں کام ابھی ہو رہا ہوتا ہے یا روز ہوتا ہے۔ جیسے: بچے کھیل رہے ہیں۔ سورج مشرق سے نکلتا ہے۔"),
   CH("",[["امی کھانا ___ ہیں۔",["پکا رہی","پکایا"],0],["چڑیا درخت پر ___ ہے۔",["بیٹھی","بیٹھے گی"],0],["میں روز دودھ ___ ہوں۔",["پیتا","پیوں گا"],0],["بچے میدان میں ___ رہے ہیں۔",["دوڑ","دوڑے"],0],["بارش ___ رہی ہے۔",["ہو","ہوئی"],0]])),
  pg("مستقبل|Future tense","جملوں کو مستقبل میں بدلیں۔","Change sentences into the future tense.",
   NO("مستقبل میں کام آگے ہوگا۔ اس کے آخر میں گا، گی یا گے آتا ہے۔ جیسے: میں کل آؤں گا۔"),
   F("",["میں کھیلتا ہوں۔ ← میں {{کھیلوں}} گا۔","وہ پڑھتی ہے۔ ← وہ {{پڑھے}} گی۔","ہم جاتے ہیں۔ ← ہم {{جائیں}} گے۔","تم لکھتے ہو۔ ← تم {{لکھو}} گے۔"],1,1)),
  pg("تین زمانے|Three tenses","ہر فعل کو تینوں زمانوں میں لکھیں۔","Write one verb in all three tenses.",
   F("",["ماضی: میں نے پانی پیا۔ | حال: میں پانی {{پیتا}} ہوں۔ | مستقبل: میں پانی {{پیوں}} گا۔","ماضی: اس نے کتاب پڑھی۔ | حال: وہ کتاب {{پڑھتی}} ہے۔ | مستقبل: وہ کتاب {{پڑھے}} گی۔","ماضی: بچے سکول گئے۔ | حال: بچے سکول {{جاتے}} ہیں۔ | مستقبل: بچے سکول {{جائیں}} گے۔"],1,1)),
  pg("الفاظ اور زمانہ|Time words","وقت بتانے والے الفاظ کو صحیح زمانے میں لکھیں۔","Sort time words by tense.",
   SO("",["ماضی","حال","مستقبل"],["پچھلے سال","آج کل","آنے والے ہفتے","پچھلے ہفتے","ابھی","اگلے سال","پچھلے مہینے","اس وقت","کچھ دن بعد"],[0,1,2,0,1,2,0,1,2])),
  pg("تصویر دیکھیں|Look at the pictures","تصویر دیکھیں اور زمانہ پہچان کر فعل لکھیں۔","Use tense with pictures.",BK(["نکلا","ہو رہا","کھلے گا"]),
   CY("",[["seedling","پچھلے ہفتے بیج سے ننھا پودا {{نکلا}}۔"],["potted-plant","آج پودا بڑا {{ہو رہا}} ہے۔"],["sunflower","کچھ دن بعد پھول {{کھلے گا}}۔"]]),
   NO("ہر جملے کا زمانہ الگ ہے: پہلا ماضی، دوسرا حال اور تیسرا مستقبل۔")),
  pg("گنتی کے سوال|Number stories","پڑھیں، زمانہ پہچانیں اور جواب لکھیں۔","Read Urdu number stories with tenses.",
   WP("",["کل ثنا نے ۱۲ صفحے پڑھے۔ آج وہ ۸ صفحے پڑھ رہی ہے۔ دونوں دنوں میں {{۲۰}} صفحے ہوں گے۔","پچھلے سال باغ میں ۲۵ درخت تھے۔ اگلے سال ۱۵ اور لگائیں گے۔ تب {{۴۰}} درخت ہوں گے۔","علی ہر روز ۳ کلومیٹر چلتا ہے۔ ایک ہفتے میں وہ {{۲۱}} کلومیٹر چلے گا۔"])),
  pg("کہانی میں زمانہ|Tense in a story","کہانی پڑھیں۔ پھر سوالوں کے جواب دیں۔","Find tenses in a story.",
   PA("پچھلی گرمیوں میں ہم نانی کے گاؤں گئے۔ وہاں ہم نے آم کھائے اور نہر میں نہائے۔ آج کل میں اپنی کاپی میں اس سفر کی کہانی لکھ رہا ہوں۔ اگلی گرمیوں میں ہم پھر گاؤں جائیں گے اور نانی کے لیے تحفہ لے جائیں گے۔"),
   F("",["ہم نانی کے گاؤں {{گئے}}۔ (ماضی)","میں کہانی {{لکھ}} رہا ہوں۔ (حال)","ہم پھر گاؤں {{جائیں}} گے۔ (مستقبل)","انہوں نے گاؤں میں {{آم}} کھائے۔"],1)),
  pg("میری ڈائری|My diary","تینوں زمانوں میں اپنے بارے میں لکھیں۔ پھر تصویر بنائیں۔","Write about yourself in three tenses.",
   WR("",["کل میں نے ____________________۔","آج میں ____________________ رہا/رہی ہوں۔","کل میں ____________________ گا/گی۔"]),DR("کل کیا کریں گے؟ تصویر بنائیں",190))],
  "Tenses (زمانہ) in Urdu: past (ماضی), present (حال) and future (مستقبل). Children spot the tense of a sentence, change verbs from one tense to another, use time words such as کل، آج، اگلے سال and find tenses in a story.",
  ["Ask three questions in Urdu: کل کیا کیا؟ ابھی کیا کر رہے ہو؟ کل کیا کرو گے؟","Point out گا، گی، گے at the end of future sentences.","Read an Urdu story and ask which tense it is told in."],
  ["Keep a three-line Urdu diary for a week: one line past, one present, one future.","Play a tense game: say a verb and ask your child to use it in all three tenses."],
  "کل can mean yesterday or tomorrow in Urdu. The verb shows which one: کل گیا (yesterday), کل جاؤں گا (tomorrow).",
  ["وقت کا پرندہ","ایک ننھا پرندہ کل گھونسلے سے باہر آیا۔ آج وہ اپنے پر پھیلا رہا ہے۔ ماں نے کہا: کل تم اڑو گے! اگلے دن ننھا پرندہ اونچا اڑا اور خوشی سے چہچہایا۔ سوال: پرندہ کس دن اڑے گا؟"])
]});

addPlus("computer",{g3:[
 TP("Spreadsheets: totals","",[
  pg("Cells, Rows and Columns","Read the big idea. Then circle true or false.","Know the parts of a spreadsheet.",
   CN(["laptop","bar-chart"],"A spreadsheet is a grid of boxes called cells. Rows go across and have numbers (1, 2, 3). Columns go down and have letters (A, B, C). Each cell has an address made of its column and row, like B3.","Spreadsheets"),
   CH("",[["Rows go across.",0],["Columns have numbers.",1],["A cell is one box in the grid.",0],["B3 means column B, row 3.",0]],TF)),
  pg("Cell Addresses","Read the grid. Write what is in each cell.","Find cells by their address.",
   NO("Row 1: A1 Fruit, B1 Monday, C1 Tuesday. Row 2: A2 Apples, B2 5, C2 7. Row 3: A3 Bananas, B3 8, C3 6. Row 4: A4 Mangoes, B4 4, C4 9."),
   F("",["A3 = {{Bananas}}","B2 = {{5}}","C4 = {{9}}","C1 = {{Tuesday}}","The cell with Mangoes is {{A4}}.","The cell with 8 is {{B3}}."],2)),
  pg("Formulas","Read the big idea. Then work out each answer.","Know that a formula does a sum for us.",
   CN(["input-numbers","desktop-computer"],"A formula always starts with an equals sign (=). It tells the computer to work something out. If A1 is 4 and A2 is 6, then =A1+A2 shows 10. If a number changes, the answer changes by itself.","Formulas"),
   F("A1 = 4, A2 = 6, A3 = 10, A4 = 3",["=A1+A2 shows {{10}}","=A3-A4 shows {{7}}","=A1*A4 shows {{12}}","=A3+A4 shows {{13}}","=A2-A1 shows {{2}}","=A3*A1 shows {{40}}"],2),
   NO("In spreadsheets, * means multiply and / means divide.")),
  pg("The SUM Function","Read the rule. Then fill in the totals.","Use SUM to add a range of cells.",
   NO("=SUM(B2:B5) adds every cell from B2 to B5. The colon (:) means to. This is quicker than =B2+B3+B4+B5."),
   F("B2 = 12, B3 = 8, B4 = 15, B5 = 5",["=SUM(B2:B3) shows {{20}}","=SUM(B2:B5) shows {{40}}","=SUM(B3:B4) shows {{23}}","=SUM(B4:B5) shows {{20}}"],2),
   CH("Which formula adds C1 to C6?",[["Pick one.",["=SUM(C1:C6)","SUM C1 C6"],0]])),
  pg("Pocket Money Tracker","Read the spreadsheet. Then answer.","Use totals to understand data.",
   NO("Column A: Week 1, Week 2, Week 3, Week 4. Column B (saved, Rs): 50, 30, 70, 40. B6 has the formula =SUM(B2:B5)."),
   WP("",["B6 shows the total saved: Rs {{190}}.","The week with the most saved is Week {{3}}.","If Week 2 changes to Rs 60, the total becomes Rs {{220}}.","To find the total, the formula starts with an {{=}} sign."])),
  pg("Fix the Formula","Each formula has a mistake. Circle the correct one.","Spot and fix formula mistakes.",
   CH("",[["Add A1 and A2",["=A1+A2","A1+A2"],0],["Total of B1 to B4",["=SUM(B1:B4)","=SUM(B1-B4)"],0],["Multiply C2 by 3",["=C2x3","=C2*3"],1],["Take D2 away from D1",["=D1-D2","=D2-D1"],0],["Add the whole of column E from E1 to E10",["=SUM(E1:E10)","=SUM(E1,E10)"],0]])),
  pg("Tools of a Spreadsheet","Match each tool to what it does.","Know useful spreadsheet tools.",
   MA("Write the letter in the box.",["AutoSum button (Σ)","Fill handle (small square at the corner of a cell)","Sort A to Z","Bold (B)","Chart button"],["adds up a column quickly","copies a formula down to the next cells","puts names in alphabetical order","makes headings stand out","turns numbers into a graph"])),
  pg("Class Survey","Read the data. Fill in the totals.","Total survey data in a spreadsheet.",
   NO("Favourite sport survey. Row 2: Cricket, boys 9, girls 6. Row 3: Football, boys 5, girls 4. Row 4: Badminton, boys 2, girls 7. Column D totals each row with =B2+C2 and so on."),
   F("",["D2 (Cricket total) = {{15}}","D3 (Football total) = {{9}}","D4 (Badminton total) = {{9}}","=SUM(B2:B4) (all boys) = {{16}}","=SUM(C2:C4) (all girls) = {{17}}","Everyone in the survey = {{33}}"],2)),
  pg("Plan Your Spreadsheet","Put the steps in order. Fill in the missing words.","Follow steps to build a spreadsheet with totals.",BK(["headings","numbers","formula","chart"]),
   CY("",[["keyboard","Type the {{headings}} in row 1"],["input-numbers","Type the {{numbers}} underneath"],["laptop","Type a {{formula}} like =SUM(B2:B6)"],["bar-chart","Make a {{chart}} to show the data"]])),
  pg("My Spending Sheet","Design a spreadsheet on paper. Then try it on a computer.","Plan a spreadsheet with a total.",
   WR("Plan a sheet for a picnic shopping list.",["A1 heading: ____________ B1 heading: ____________","A2 to A5 items: ________, ________, ________, ________","B2 to B5 prices: ________, ________, ________, ________","Formula in B6 for the total: ____________________"]),DR("Draw your spreadsheet grid",170))],
  "Spreadsheets with totals: cells, rows, columns and cell addresses (B3), formulas that start with =, the +, -, * and / signs, the SUM function with ranges (B2:B5), AutoSum and the fill handle, and using totals to answer questions.",
  ["Open a free spreadsheet app and type a family shopping list together.","Change a number and watch the total update by itself.","Say cell addresses aloud: column letter first, then row number."],
  ["Keep a spreadsheet of pocket money or reading minutes for a month.","Make a chart from a class or family survey."],
  "Children often forget the = sign, so the formula shows as text. They may also mix up rows (numbers, across) and columns (letters, down).",
  ["The Magic Total","Bilal kept his savings in a spreadsheet. One week he typed the wrong number, but when he fixed it, the total at the bottom changed all by itself. 'It's magic!' he said. His sister laughed: 'No, it's a formula!' Ask: What starts every formula?"])
]});

