addPlus("computer",{g3:[
 TP("Cyberbullying and kindness","",[
  pg("What Is Cyberbullying?","Read the big idea. Then circle true or false.","Know what cyberbullying is.",
   CN(["mobile-phone","pensive-face"],"Bullying is when someone is unkind to another person on purpose, again and again. Cyberbullying is bullying that happens online: in chats, games, messages or comments. It can mean sending mean messages, sharing embarrassing photos, spreading lies or leaving someone out of a group on purpose.","Cyberbullying"),
   CH("",[["Cyberbullying happens online.",0],["Sending mean messages again and again is bullying.",0],["Leaving someone out of a group chat on purpose can be bullying.",0],["Cyberbullying is just a joke, so it does not hurt.",1],["Sharing someone's photo to laugh at them is kind.",1]],TF)),
  pg("Kind or Unkind?","Look at each picture. Circle kind or unkind.","Tell kind and unkind online actions apart.",
   CP("",[["thumbs-up","Writing 'Great drawing!' under a friend's picture",0],["pouting-face","Calling someone names in a game chat",1],["camera","Sharing a funny photo of a friend without asking",1],["hugging-face","Sending a message to cheer up a sad friend",0],["prohibited","Telling others not to let a child join the game",1],["speech-balloon","Saying sorry when you upset someone",0]],["kind","unkind"])),
  pg("How Does It Feel?","Read the big idea. Then choose the answer.","Understand how bullying makes people feel.",
   CN(["crying-face","red-heart"],"Words on a screen can hurt just as much as words said out loud. Being bullied can make someone feel sad, scared, lonely or worried about going to school. Because messages can be seen by many people and saved, the hurt can last a long time. Remember there is a real person behind every screen.","Feelings"),
   CH("",[["Mean words online can make people feel",["sad and lonely","happy"],0],["Can online messages be seen by many people?",["yes","no"],0],["Behind every screen there is",["a real person","only a computer"],0],["Online words can hurt",["as much as spoken words","less than nothing"],0]])),
  pg("Stop, Block, Tell","Follow the steps. Fill in the blanks.","Know what to do if you are bullied online.",BK(["reply","save","block","tell","adult"]),
   CY("",[["stop-sign","1. Stop: do not {{reply}}"],["camera-with-flash","2. With a grown-up, {{save}} the messages"],["prohibited","3. {{block}} the bully"],["speaking-head","4. {{tell}} someone you trust"],["woman-teacher","5. A trusted {{adult}} helps sort it out"]])),
  pg("Be an Upstander","Read the rule. Then match each problem to an upstander action.","Know how to help someone who is being bullied.",
   NO("A bystander sees bullying and does nothing. An upstander does something kind to help. You can support the person, refuse to join in, and tell a grown-up. You do not have to fight the bully yourself."),
   MA("Write the letter in the box.",["Someone posts a mean comment about a classmate","Friends are laughing at an embarrassing photo","A child is left out of the game","A friend looks upset after reading a message","Someone asks you to forward a mean message"],["do not like or share it, and tell a grown-up","do not laugh, and ask them to delete it","invite the child to play with you","ask if they are OK and listen","say no and delete it"])),
  pg("THINK Before You Post","Read the rule. Then fill in the blanks.","Use THINK to check messages before posting.",BK(["True","Helpful","Inspiring","Necessary","Kind"]),
   NO("Before you post or send something, THINK. Is it True? Is it Helpful? Is it Inspiring? Is it Necessary? Is it Kind? If the answer is no, do not post it."),
   F("",["T stands for {{True}}.","H stands for {{Helpful}}.","I stands for {{Inspiring}}.","N stands for {{Necessary}}.","K stands for {{Kind}}."],1)),
  pg("Kind Words Online","Look at each picture. Fill in the kind word.","Write kind messages.",BK(["proud","welcome","better","happy","sorry","help"]),
   FP("",[["sports-medal","Well done in the race! I am so {{proud}} of you."],["waving-hand","{{welcome}} to our group, Zain!"],["adhesive-bandage","Hope you feel {{better}} soon."],["party-popper","{{happy}} birthday! Have a great day."],["pensive-face","I am {{sorry}} I upset you."],["raised-hand","Do you need {{help}} with the homework?"]],2)),
  pg("What Would You Do?","Read each story. Circle the best choice.","Make safe and kind choices online.",
   CH("",[["A player in an online game keeps calling you names.",["Block them and tell a grown-up","Call them names back"],0],["A classmate sends you a mean joke about another child.",["Do not send it on","Share it with everyone"],0],["You posted something unkind by mistake.",["Delete it and say sorry","Leave it there"],0],["Someone threatens you in a message.",["Save it and tell a grown-up at once","Keep it a secret"],0],["A new child joins your class group chat.",["Say hello and welcome them","Ignore them on purpose"],0]])),
  pg("Kindness Maths","Read and solve.","Use maths with online kindness.",
   WP("",["Hira writes 3 kind comments a day for 5 days. She writes {{15}} kind comments.","A class of 32 children each sends 1 thank-you message to a teacher. That is {{32}} messages.","A game chat had 40 messages. 8 were unkind and were deleted. {{32}} messages were left.","Saad helps 2 friends a day for a week. He helps {{14}} times.","20 children signed a kindness pledge. 15 more signed the next day. Now {{35}} children have signed."])),
  pg("My Kindness Pledge","Write your pledge. Then draw.","Plan to be kind and safe online.",
   WR("",["Online I will always ____________________________","Before I post I will ____________________________","If I see bullying I will ____________________________","A trusted grown-up I can tell is ____________________"]),DR("Draw a poster: Be kind online!",170))],
  "Cyberbullying and kindness: what cyberbullying is, kind and unkind online actions, how bullying feels, stop, save, block and tell, being an upstander, THINK before you post, writing kind messages, choosing what to do in real situations, and making a kindness pledge.",
  ["Talk about the games and chats your child uses and who they talk to there.","Agree together who your child can tell if something online upsets them.","Practise blocking and reporting on a game or app together."],
  ["Send a kind message to a relative or friend as a family.","Make a THINK poster and stick it near the computer or tablet."],
  "Children may think unkind messages are just jokes, or worry they will lose their tablet if they tell. Reassure them that telling a grown-up is always the right thing, and they will not be in trouble for it.",
  ["The Group Chat","Zoya's class had a group chat. One day, someone posted a silly photo of Bilal with a mean caption. Some children sent laughing faces. Zoya felt uneasy. She did not laugh. She wrote, 'That's not kind. Please delete it.' Then she told her mother, who spoke to the teacher. The next day, Zoya sat with Bilal at lunch. Ask: How was Zoya an upstander?"])
]});
